\begin{equation}\label{eq:2.1}
% (2.1).\
\raisetag{3ex}
\begin{aligned}[t]
\alpha\circ(\beta_1\pm\beta_2)
&=\alpha\circ\beta_1\ \pm\ \alpha\circ\beta_2,\\
(\alpha_1\pm\alpha_2)\circ E\beta
&=\alpha_1\circ E\beta\ \pm\ \alpha_2\circ E\beta,
