\begin{equation}\label{eq:2.7}
H\ :=\ \Omega_1^{-1}\circ h_{m*}\circ \Omega_1:\ 
[EK, S^{m+1}]\ \longrightarrow\ [EK, S^{2m+1}]
\tag{2.7}
\end{equation}

\begin{equation}\label{2.8}
\cdots\ \to\ \pi_i(S^m)\ \to\ \pi_i\bigl((S^m)_\infty\bigr)\ \to\
\pi_i\bigl((S^m)_\infty,\ S^m\bigr)\ \xrightarrow{\ \partial\ }\ \pi_{i-1}(S^m)\ \to\ \cdots
\tag{2.8}
\end{equation}

\begin{equation}\label{2.9}
\Delta\ :=\ \partial\ \circ\ (h_{m*})^{-1}\ \circ\ \Omega_1:\ 
\pi_{i+1}(S^{2m+1})\ \longrightarrow\ \pi_{i-1}(S^m)\big/\partial\Ker(h_{m*})
\tag{2.9}
\end{equation}

\begin{equation}\label{2.10}
\Delta^{-1}\ :=\ \Omega_1^{-1}\ \circ\ h_{m*}\ \circ\ \partial^{-1}:\ 
\pi_{i-1}(S^m)\ \longrightarrow\ 
\pi_{i+1}(S^{2m+1})\big/ H\pi_{i+1}(S^{m+1})
\tag{2.10}
\end{equation}

\begin{equation}\label{2.11}
% (2.11).\
\cdots\ \longrightarrow\ 
\pi_i(S^m)\xrightarrow{\,E\,}\pi_{i+1}(S^{m+1})\xrightarrow{\,H\,}
\pi_{i+1}(S^{2m+1})\xrightarrow{\,\Delta\,}\pi_{i-1}(S^m)\xrightarrow{\,E\,}\cdots
\tag{2.11}
\end{equation}

\begin{proposition}\label{prop:2.7}
% Prop2.7.\
$n$ が偶数のとき,
\[
H\!\bigl(\Delta(\iota_{2n+1})\bigr)\ =\ \pm\,2\,\iota_{2n-1}
\qquad (\text{cf.} (11.14)).
\]
\end{proposition}

\begin{equation}\label{3.1}
% (3.1)
\bigl(1-(-1)^k\bigr)\, \Ex^{\,n-h}\alpha \circ \Ex^{\,n+k-h}\alpha = 0.
\end{equation}

\begin{corollary}\label{cor:3.7}
% Cor3.7
整数 $r$ をとる. $\beta\in\pis{m+k}{S^m}$, $(k>0)$ が $r\beta=0$ を満たすとき,
\[
\todai[1]{\,r\,\iota_{m+1},\ \Ex\beta,\ r\,\iota_{m+k+1}\,}
\begin{cases}
\equiv 0, & r\not\equiv 2 \pmod 4,\\[4pt]
\ni\Ex\beta\circ \eta_{m+k+1}, & r\equiv 2 \pmod 4 .
\end{cases}
\]
ここで, $\eta_{m+k+1}$ は $\pis{m+k+2}{S^{m+k+1}}\cong\mathbb{Z}_2$ の生成元とする. 
\end{corollary}

\begin{equation}\label{3.2}
% (3.2)
\Ex: \pis{i}{S^m} \longrightarrow \pis{i+1}{S^{m+1}}
\quad\text{は, } i<2m-1 \text{で同型, } i=2m-1 \text{で全射である. }
\end{equation}

\begin{equation}\label{3.3}
% (3.3)
\Ex^\infty:\ \pis{n+k}{S^n}\ \xrightarrow{\;\;}\ G_k
\quad\text{は, } n>k+1 \text{で同型, } n=k+1 \text{で全射である. }
\end{equation}

\begin{equation}\label{3.4}
% (3.4)
\alpha\circ\beta=(-1)^{kh}\,\beta\circ\alpha,
\qquad(\alpha\in G_k,\ \beta\in G_h) .
\end{equation}

\begin{equation}\label{3.prop-zero}
% (3.5)
\raisetag{3ex}
  \begin{aligned}[t]
    \text{0).}\ & \todas{\alpha, \beta, \gamma}\equiv 0,
    \qquad\text{ ($\alpha,\beta,\gamma$ のいずれかが $0$ のとき) }.
    \qquad\qquad\qquad\qquad\qquad\\
    \text{i).}\ & \todas{\alpha, \beta, \gamma}\circ\delta
    \subset \todas{\alpha, \beta, \gamma\circ\delta}\\
    \text{ii).}\ & \todas{\alpha, \beta, \gamma\circ\delta}
    \subset \todas{\alpha, \beta\circ\gamma, \delta}\\
    \text{iii).}\ & \todas{\alpha\circ\beta, \gamma, \delta}
    \subset \todas{\alpha, \beta\circ\gamma, \delta}\\
    \text{iv).}\ & \alpha\circ\todas{\beta, \gamma, \delta}
    \subset (-1)^k\todas{\alpha\circ\beta, \gamma, \delta},\ \alpha\in G_k .
  \end{aligned}
\end{equation}

\begin{equation}\label{3.6-stable}
\todas{\alpha,\beta,\gamma}\circ\delta
 = (-1)^{k+1}\,\alpha\circ\todas{\beta,\gamma,\delta},
\qquad \alpha\in G_k.
\end{equation}

\begin{equation}\label{3.7-stable}
% (3.8)
0\ \in\
\todas{\todas{\alpha,\beta,\gamma},\,\delta,\,\varepsilon}
\ +\ (-1)^{k}\,\todas{\alpha,\,\todas{\beta,\gamma,\delta},\,\varepsilon}
\ +\ (-1)^{k+h}\,\todas{\alpha,\,\beta,\,\todas{\gamma,\delta,\varepsilon}}.
\end{equation}

\begin{equation}\label{3.8-stable}
% (3.8)
\raisetag{3ex}
\begin{aligned}[t]
\todas{\alpha,\beta,\gamma}\ +\ \todas{\alpha,\beta,\gamma'}\ &\supset\
\todas{\alpha,\beta,\,\gamma+\gamma'},\\
\todas{\alpha,\beta,\gamma}\ +\ \todas{\alpha,\beta',\gamma}\ &=\
\todas{\alpha,\,\beta+\beta',\,\gamma},\\
\todas{\alpha,\beta,\gamma}\ +\ \todas{\alpha',\beta,\gamma}\ &\supset\
\todas{\,\alpha+\alpha',\,\beta,\,\gamma}.
\end{aligned}
\end{equation}

\begin{equation}\label{3.9-stable}
% \noindent
% \textbf{(3.9).}\
\raisetag{3ex}
  \begin{aligned}[t]
    \text{i).}\ & \todas{\alpha,\beta,\gamma}\ \subset\
    (-1)^{hk+k\ell+\ell h+1}\ \todas{\gamma,\beta,\alpha},\\
    \text{ii).}\ & (-1)^{k\ell}\ \todas{\alpha,\beta,\gamma}\ +\
    (-1)^{hk}\ \todas{\beta,\gamma,\alpha}\ +\
    (-1)^{\ell k}\ \todas{\gamma,\alpha,\beta}\ \ni\ 0 .
    \qquad\qquad\qquad
  \end{aligned}
\end{equation}

\begin{equation}\label{prop:3.10}
% (3.10)
\raisetag{3ex}
  \begin{aligned}[t]
    & k \text{ が奇数のとき, } \todas{\alpha,\beta,\alpha} \text{ と }
    (-1)^{h}\,\todas{\beta,\alpha,2\alpha} \text{ は共通元を持つ. }\\
    & k \text{ が偶数のとき, } \todas{\alpha,\beta,\alpha} \text{ と }
    \beta\circ G_{2k+1} \text{ は共通元を持つ. }
    \qquad\qquad\qquad\qquad\qquad\\
  \end{aligned}
\end{equation}

\begin{equation}\label{4.1}
\pis{i}{S^1}=0\ (i>1),\qquad
\pis{i}{S^n}=0\ (i<n),\qquad
\pis{n}{S^n}\cong \mathbb{Z}\gen{\iota_n} .
\end{equation}

\begin{equation}\label{4.2}
% (4.2).\
\pis{i}{S^n}\ \text{は,} \ i=n \ \text{または} \ 
i=2n-1 \ \text{のとき以外は, 有限群である. }
\end{equation}

\begin{equation}\label{4.3}
\pi_i^n :=
\begin{cases}
\pis{n}{S^n}, & i=n,\\[2pt]
\Ex^{-1}\bigl(\pis{2n}{S^{n+1};2}\bigr), & i=2n-1,\\[2pt]
\pis{i}{S^n;2}, & i\ne n,\,2n-1 .
\end{cases}
\end{equation}

\begin{proposition}[]\label{prop:4.2}
% Prop4.2.\
次の列は完全列である：
\begin{equation}\label{4.4}
% (4.4)
\cdots \longrightarrow
\pit{i}{n}\ \xrightarrow{\ \Ex\ }\ \pit{i+1}{n+1}\
\xrightarrow{\ H\ }\ \pit{i+1}{2n+1}\
\xrightarrow{\ \Delta\ }\ \pit{i-1}{n}\
\xrightarrow{\ \Ex\ }\ \pit{i}{n+1}\ \xrightarrow{\ H\ }\ \cdots.
\end{equation}
\end{proposition}

\begin{equation}\label{4.5}
% (4.5)
\Ex^{\,m-n}:\pit{n+k}{n}\xrightarrow{\cong}\pit{m+k}{m}\quad(m\ge n),\ \ \
\Ex^{\infty}:\pit{n+k}{n}\xrightarrow{\cong}(G_k;2)
\quad(n\ge k+2).
\end{equation}

\begin{equation}\label{4.6}
% (4.6).\
\raisetag{3ex}
\begin{aligned}[t]
  &n\ge 1,\ p^r\alpha=0,\ p^s\gamma=0,\ r,s>0,\ 
  \alpha\in[E^n Y, Z],\ \gamma\in[EW, X] \ \text{のとき, }\\
  &\beta\in[X, Y]\ \text{に対して, } \ 
  p^r(\alpha\circ E^r\beta) = 0,\ p^s(\beta\circ\gamma) = 0 \ \text{である. }\\
  &\text{さらに, }\ \alpha\circ E^n\beta=0,\ \beta\circ\gamma = 0 \ \text{のとき, }
  p^{r+s}\todai[n]{\alpha, E^n\beta, E^n\gamma} = 0 \ \text{である. }\qquad
\end{aligned}
\end{equation}

\begin{equation}\label{4.7}
% (4.7).\
\raisetag{3ex}
\begin{aligned}[t]
  & n\ge1, \ \alpha\in\pis{k+n}{S^m; 2},\ \gamma\in\pis{i}{S^j; 2}
    \ \text{のとき, }\\
  & \alpha\circ E^n\pis{j}{S^k} = \alpha\circ E^n \pit{j}{k}
  \subset \pit{j+n}{m},
  \ \pis{j}{S^k}\circ\gamma = \pit{j}{k}\circ\gamma \subset\pit{i}{k}\ . \\
  &\text{さらに, }\ \alpha\circ E^n\beta=0,\ \beta\circ\gamma = 0 \ \text{のとき, }\\
  & \todai[n]{\alpha, E^n\beta, E^n\gamma}\ \text{は,}\
  \alpha\circ E^n\pit{i+1}{k} + \pit{j+n+1}{m}\circ E^{n+1}\gamma\
  \text{の coset で, }\qquad\qquad\qquad\\
  & \pit{i+n+1}{m} \ \text{の部分集合である. }
\end{aligned}
\end{equation}

\begin{equation}\label{4.8}
% (4.8).\
\raisetag{3ex}
\begin{aligned}[t]
& n \ \text{を偶数とする. } \\
& \Delta(\iota_{2n-1})=[\iota_{n-1},\iota_{n-1}]\ne0 \ \text{のとき, }\\
& \pit{2n-1}{n}
=E\,\pit{2n-2}{\,n-1}\ \oplus\ \Delta\,\pit{2n+1}{\,2n+1}
\cong E\,\pit{2n-2}{\,n-1}\ \oplus\ \mathbb{Z},\ \pit{2n}{\,n+1} = E^{2}\,\pit{2n-2}{\,n-1} 
\cong E\,\pit{2n-2}{\,n}.\\
& \Delta(\iota_{2n-1})=0 \ \text{のとき, }\\
& E^{2}:\pit{2n-2}{\,n-1}\to\pit{2n}{\,n+1}\ \text{は単射で, }\
\pit{2n}{\,n+1}/E^{2}\pit{2n-2}{\,n-1}\cong\mathbb{Z}_2 . \\
& \text{さらに,}\ \alpha\in\pit{2n-1}{n} \ \text{に対して, 次が成り立つ. }\\
& E\alpha\in E^{2}\pit{2n-2}{\,n-1} \ \Leftrightarrow \
H(\alpha)\in 2\,\pit{2n-1}{\,2n-1}\ .
\end{aligned}
\end{equation}

\begin{equation}\label{4.9}
% \noindent
% \textbf{(4.9).}\
\pit{m}{n}\circ\pit{k}{m}\ \subset\ \pit{k}{n}.
\end{equation}

\begin{equation}\label{5.1}
\pi^{1}_{i}=0\ (i>1),\qquad
\pi^{n}_{i}=0\ (i<n),\qquad
G_k=(G_k;2)=0\ (k<0).
\end{equation}

\begin{equation}\label{eq:5.2}
% (5.2).\
\text{合成 } \alpha\longmapsto \eta_2\circ \alpha \text{ は, 同型 } 
\pi^{3}_{i}\xrightarrow{\cong}\pi^{2}_{i}\ (i\ge3) 
\text{ を定める. }
\end{equation}

\begin{equation}\label{eq:5.3}
% (5.3).\
\nu'\in\pi_6^3,\ H(\nu')=\eta_5,\ 2\nu'=\eta_3\circ\eta_4\circ\eta_5 .
\end{equation}

\begin{proposition}\label{prop:5.3}
% Prop5.3.\
\(\pi^{n}_{n+2}=\gen{\eta_n^{2}}\cong \mathbb Z_2\ (n\ge2).\) \
\((G_2;2)=\gen{\eta^{2}}\cong \mathbb Z_2 .\)
\end{proposition}

\begin{equation}\label{eq:5.4}
% (5.4).\
\todai[t]{\eta_{n},\,2\iota_{n+1},\,\eta_{n+1}} = \{E^{\,n-3}\nu',-E^{\,n-3}\nu'\}.
\end{equation}

\begin{equation}\label{eq:5.5}
% (5.5).\
n\ge5\ \text{に対して, } 2\nu_n=E^{\,n-3}\nu',\qquad
4\nu_{n}=\eta_n^{3},\quad 4\nu=\eta^{3}.
\end{equation}

\begin{equation}\label{eq:5.6}
% (5.6).\
(\alpha,\beta)\ \longmapsto\ E\alpha+\nu_{4}\circ\beta
\quad\text{は,}\quad
\pi^{\,3}_{i-1}\oplus \pi^{\,7}_{i}\ \xrightarrow{\ \cong\ }\ \pi_{\,i}^{4}
\ \text{の同型を与える. }
\end{equation}

\begin{equation}\label{eq:5.7}
% (5.7).\
H(\nu'\circ\eta_6)=\eta_5^2 .
\end{equation}

\begin{equation}\label{eq:5.8}
% (5.8).\
\Delta(\iota_9)=\pm(2\nu_4-E\nu')  \ (=\pm[\iota_4, \iota_4]) .
\end{equation}

\begin{equation}\label{eq:5.9}
% (5.9).\
\eta_3\circ \nu_4= \nu'\circ \eta_6,\qquad
\eta_n\circ \nu_{n+1}=0\ (n\ge5),\qquad
\nu_n\circ \eta_{n+3}=0\ (n\ge6)
\end{equation}

\begin{equation}\label{eq:5.10}
% (5.10).\
\Delta(\iota_{11})=\nu_5\circ\eta_8 .
\end{equation}

\begin{equation}\label{eq:5.11}
% (5.11).\
\Delta(\eta_9)=E\nu'\circ\eta_7 .
\end{equation}

\begin{equation}\label{eq:5.12}
% (5.12).\
\Delta:\ \pi^{2n+1}_{n+7}\ \longrightarrow\ \pi^{n}_{n+5}
\quad\text{は, }n=4,5,6\text{ で単射である. }
\end{equation}

\begin{lemma}\label{lemma:5.10}
% Lem5.10.\
\[
\Delta(\iota_{13})\in\toda{\nu_6,\eta_9,2\iota_{10}}\in\pi_{11}(S^6)/2\pi_{11}(S^6) .
\]
\end{lemma}

\begin{equation}\label{eq:5.13}
% (5.13).\
\Delta(\nu_9)=\pm\,2(\nu_4^{2}),\qquad
\Delta(\eta^{2}_{11})=0,\qquad
\Delta(\eta_{13})=0.
\end{equation}

\begin{lemma}\label{lemma:5.12}
% \noindent
% \textbf{Lem5.12.}\
\(\toda{\eta_n,\nu_{n+1},\eta_{n+4}} = \gen{\nu_n^2},\ (n\geq6) .\)
\end{lemma}

\begin{equation}\label{eq:5.14}
% (5.14).\
0\to \pi^{5}_{12}\xrightarrow{E}\pi^{6}_{13}\xrightarrow{H}\pi^{11}_{13}\to0,
\qquad
0\to \pi^{6}_{13}\xrightarrow{E}\pi^{7}_{14}\xrightarrow{H}\pi^{13}_{14}\to0.
\end{equation}

\begin{equation}\label{eq:5.15}
% \noindent
% \textbf{(5.15).}\
(\alpha,\beta)\ \longmapsto\ E\alpha+\sigma_{8}\circ\beta
\quad\text{は,}\quad
\pi^{7}_{i-1}\oplus\pi^{15}_{i}\xrightarrow{\cong}\pi^{8}_{i}
\ \text{の同型を与える. }
\end{equation}

\begin{equation}\label{eq:5.16}
% \noindent
% \textbf{(5.16).}\
\Delta(\iota_{17})=\pm\,(2\sigma_{8}-E\sigma').
\end{equation}
